FUNCTION_BLOCK FB_Contador
VAR_INPUT
    sensorPieza : BOOL; // Sensor fotoeléctrico que detecta la pieza
    btnReset : BOOL;    // Botón de reset para reiniciar el contador
END_VAR

VAR_OUTPUT
    loteListo : BOOL; // Salida que indica que se ha completado un lote
    cuenta : INT;      // Contador de piezas
END_VAR

VAR
    sensorAnterior : BOOL; // Variable para almacenar el estado anterior del sensor
END_VAR

// Inicialización del sensorAnterior con el valor actual del sensorPieza
IF sensorPieza THEN
    sensorAnterior := TRUE;
ELSE
    sensorAnterior := FALSE;
END_IF

// Lógica de conteo
IF sensorPieza AND NOT sensorAnterior THEN
    cuenta := cuenta + 1;
END_IF

// Actualización del sensorAnterior
sensorAnterior := sensorPieza;

// Lógica para detectar el lote completo
IF cuenta >= 12 THEN
    loteListo := TRUE;
ELSE
    loteListo := FALSE;
END_IF

// Lógica de reset
IF btnReset THEN
    cuenta := 0;
    loteListo := FALSE;
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Contador

VAR_INPUT
    sensorPieza : BOOL; // Entrada del sensor fotoeléctrico
    btnReset : BOOL;    // Botón para reiniciar el conteo y el lote
END_VAR

VAR_OUTPUT
    loteListo : BOOL;   // Se activa al llegar a 12 piezas
    cuenta : INT;       // Cantidad actual de piezas contadas
END_VAR

VAR
    flancoSensor : R_TRIG; // Instancia para detectar el flanco de subida
END_VAR

// Evaluar la transición de FALSE a TRUE del sensor
flancoSensor(CLK := sensorPieza);

// Lógica de reinicio y conteo
IF btnReset THEN
    cuenta := 0;
    loteListo := FALSE;
ELSIF flancoSensor.Q THEN
    cuenta := cuenta + 1;
END_IF;

// Lógica para activar la salida de lote completo
IF cuenta >= 12 THEN
    loteListo := TRUE;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Contador
VAR_INPUT
    sensorPieza : BOOL;   // Entrada del sensor fotoeléctrico
    btnReset : BOOL;      // Botón de reset
END_VAR

VAR_OUTPUT
    loteListo : BOOL;     // Indica si el lote está completo
    cuenta : INT;         // Cuenta de piezas
END_VAR

VAR
    lastSensorState : BOOL; // Estado anterior del sensor
END_VAR

// Inicialización de variables
IF btnReset THEN
    cuenta := 0;
    loteListo := FALSE;
END_IF

// Detección de flanco ascendente del sensor
IF (sensorPieza AND NOT lastSensorState) THEN
    cuenta := cuenta + 1;
END_IF

// Comprobación si el lote está completo
IF cuenta >= 12 THEN
    loteListo := TRUE;
ELSE
    loteListo := FALSE;
END_IF

// Actualización del estado anterior del sensor
lastSensorState := sensorPieza;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Contador
VAR_INPUT
    sensorPieza : BOOL;   // Entrada del sensor fotoeléctrico
    btnReset : BOOL;      // Botón de reset
END_VAR

VAR_OUTPUT
    loteListo : BOOL;     // Salida que indica si el lote está completo
    cuenta : INT;         // Contador de piezas
END_VAR

VAR
    sensorPiezaAnt : BOOL; // Estado anterior del sensor
END_VAR

// Inicialización de variables
sensorPiezaAnt := FALSE;
cuenta := 0;
loteListo := FALSE;

// Cuerpo del bloque de función
IF btnReset THEN
    // Si se presiona el botón de reset, reiniciar el contador y la salida de lote
    cuenta := 0;
    loteListo := FALSE;
ELSE
    // Detectar flanco ascendente del sensor
    IF (sensorPieza AND NOT sensorPiezaAnt) THEN
        // Incrementar el contador al detectar una pieza
        cuenta := cuenta + 1;
    END_IF;

    // Verificar si se ha completado el lote
    IF cuenta >= 12 THEN
        loteListo := TRUE;
    ELSE
        loteListo := FALSE;
    END_IF;
END_IF;

// Actualizar el estado anterior del sensor
sensorPiezaAnt := sensorPieza;

END_FUNCTION_BLOCK
